from collections import deque
R,C=len(g),len(g[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if g[r][c]!=6 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); comp=[]; edges=set()
  while q:
   x,y=q.pop();comp.append((x,y))
   if x==0: edges.add('top')
   if x==R-1: edges.add('bottom')
   if y==0: edges.add('left')
   if y==C-1: edges.add('right')
   for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
    a,b=x+dx,y+dy
    if 0<=a<R and 0<=b<C and g[a][b]==6 and (a,b) not in seen: seen.add((a,b));q.append((a,b))
  comps.append((len(comp),edges,(min(x for x,y in comp),max(x for x,y in comp),min(y for x,y in comp),max(y for x,y in comp)),comp))
[(n,e,b) for n,e,b,_ in comps]

